window.kbPageData["views/entry/k-c42e11761c223003"] = {"key":"entry/k-c42e11761c223003","state":{"route":"entry/k-c42e11761c223003"},"node":{"id":"k-c42e11761c223003","mode":"k","title":"坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保持清正廉洁","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"2.坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保\n持清正廉洁\n坚定理想信念：增强党性，“坚定理想信念”居于首位，要坚定马克思主义信仰，坚\n定共产主义远大理想，坚定中国特色社会主义信念。坚定理想信念，坚守共产党人精神追\n求，始终是共产党人安身立命的根本，始终是每名党员干部增…","sources":[{"id":"cb655afd8c44625f","label":"坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保持清正廉洁","topic":"党政制度与理论","category":"非时政","text":"2.坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保\n持清正廉洁\n坚定理想信念：增强党性，“坚定理想信念”居于首位，要坚定马克思主义信仰，坚\n定共产主义远大理想，坚定中国特色社会主义信念。坚定理想信念，坚守共产党人精神追\n求，始终是共产党人安身立命的根本，始终是每名党员干部增强党性、炼就“金刚不坏之\n身”的关键所在。\n铸牢对党忠诚：“天下至德，莫大于忠”，对党忠诚，是共产党人最重要的政治品质。\n中国共产党一路走来，经历过无数艰险和磨难，没有被任何困难压垮，靠的就是千千万万\n党员的忠诚，忠诚于党的理想信念、忠诚于党的奋斗目标、忠诚于党的伟大事业，铁心跟\n党走，虽九死而不悔，用对党忠诚的气节和行动构筑了不屈的精神脊梁。\n厚植为民情怀：江山就是人民、人民就是江山，打江山、守江山，守的是人民的心。\n厚植为民情怀，是贯穿于我们党的性质宗旨、历史实践和面向未来的必然要求，是党永葆\n生机活力、赢得民心的关键所在。\n坚持实事求是：实事求是，是马克思主义的根本观点，是中国共产党人认识世界、改\n造世界的根本要求，是我们党的基本思想方法、工作方法、领导方法。坚持从实际出发、\n实事求是，不只是思想方法问题，也是党性强不强问题。\n纯正道德品质：涵养高尚的道德品质是我们党对党员干部的一贯要求，只有不断加强\n党性锤炼，明大德、守公德、严私德，其才方能用得其所。\n保持清正廉洁：“廉者，政之本也”。清正廉洁是共产党人的立身之本，更是不能丢\n弃的底色。保持清正廉洁的政治本色是党性修养的重要内容。","source":{"doc":"41195a191a57c1c36332","first":13,"last":14,"page":13,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-c42e11761c223003":[]}};
